const sponsorSlots = `-- name: SponsorSlots :many
SELECT s.id, s.workspace_id, s.list_id, s.name, s.placement, s.price_cents, s.currency, s.first_number, s.first_on, s.every_days, s.creative_days, s.selling, s.created_by, s.created_at, s.updated_at, s.deleted_at, l.name AS list_name
FROM sponsor_slots s JOIN lists l ON l.id = s.list_id
WHERE s.workspace_id = $1 AND s.deleted_at IS NULL
ORDER BY s.created_at
`

type SponsorSlotsRow struct {
	ID           uuid.UUID  `json:"id"`
	WorkspaceID  uuid.UUID  `json:"workspaceId"`
	ListID       uuid.UUID  `json:"listId"`
	Name         string     `json:"name"`
	Placement    string     `json:"placement"`
	PriceCents   int64      `json:"priceCents"`
	Currency     string     `json:"currency"`
	FirstNumber  int32      `json:"firstNumber"`
	FirstOn      time.Time  `json:"firstOn"`
	EveryDays    int32      `json:"everyDays"`
	CreativeDays int32      `json:"creativeDays"`
	Selling      bool       `json:"selling"`
	CreatedBy    *uuid.UUID `json:"createdBy"`
	CreatedAt    time.Time  `json:"createdAt"`
	UpdatedAt    time.Time  `json:"updatedAt"`
	DeletedAt    *time.Time `json:"deletedAt"`
	ListName     string     `json:"listName"`
}

func (q *Queries) SponsorSlots(ctx context.Context, workspaceID uuid.UUID) ([]SponsorSlotsRow, error) {
	rows, err := q.db.Query(ctx, sponsorSlots, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SponsorSlotsRow{}
	for rows.Next() {
		var i SponsorSlotsRow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.ListID,
			&i.Name,
			&i.Placement,
			&i.PriceCents,
			&i.Currency,
			&i.FirstNumber,
			&i.FirstOn,
			&i.EveryDays,
			&i.CreativeDays,
			&i.Selling,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
			&i.ListName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

